SELECT ticket_id, status
FROM support_tickets
WHERE payload ->> 'channel' = 'chat';

SELECT invoice_id, MAX(attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts
GROUP BY invoice_id;

SELECT customer_id, risk_score
FROM (
    SELECT customer_id, risk_score,
           ROW_NUMBER() OVER (
               PARTITION BY customer_id
               ORDER BY assessed_at DESC, assessment_id DESC
           ) AS rn
    FROM risk_assessments
) AS ranked
WHERE rn = 1;

SELECT investigation_id, EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600 AS resolution_hours
FROM investigations
WHERE closed_at IS NOT NULL;

SELECT product_id, on_hand_qty
FROM (
    SELECT product_id, on_hand_qty,
           ROW_NUMBER() OVER (
               PARTITION BY product_id
               ORDER BY snapshot_at DESC, snapshot_id DESC
           ) AS rn
    FROM inventory_snapshots
) AS latest
WHERE rn = 1;
